protected int resolveLabel(LabelNode label) {
  if (labels.containsKey(label)) {
    return labels.get(label);
  } else {
    int newLabelIndex = labels.size() + 1;
    try {
      labels.put(label, newLabelIndex);
    } catch (UnsupportedOperationException | IllegalArgumentException | ClassCastException | NullPointerException e) {
      // Handle the exception (e.g., log, throw a custom exception, or take corrective action)
      e.printStackTrace();
      throw new RuntimeException("An error occurred while adding the label to the map.", e);
    }
    return newLabelIndex;
  }
}
